function hikePhoto(item) {
  return hikePhotos[(item.mountainId ? coursePhotos : mountainPhotos)[item.id]];
}
function hikeThumbnail(item) {
  const photo = hikePhoto(item);
  return photo ? `<img class="hike-row__image" loading="lazy" src="${photo.src}" alt="">` : '';
}
function showHikeCover(id, item) {
  const cover = document.getElementById(id);
  const photo = hikePhoto(item);
  cover.parentElement.hidden = !photo;
  if (!photo) return;
  cover.src = photo.src;
  cover.alt = photo.place;
  const credit = cover.parentElement.querySelector('.hike-credit');
  credit.textContent = [photo.place, photo.author, photo.license].filter(Boolean).join(' · ');
  credit.href = photo.source;
}
